def main():
    db = SessionLocal()
    try:
        added = 0
        skipped = 0
        for car_data in NEW_CARS:
            existing = db.query(Car).filter(
                Car.marca == car_data["marca"],
                Car.model == car_data["model"],
                Car.an == car_data["an"],
            ).first()
            if existing:
                skipped += 1
                continue
            car = Car(**car_data)
            db.add(car)
            added += 1
        db.commit()
        total = db.query(Car).count()
        print(f"OK: {added} masini noi adaugate, {skipped} sarite (existau deja).")
        print(f"Total in catalog: {total}")
    finally:
        db.close()


if __name__ == "__main__":
    main()
